package main

import (
	"fmt"
	"sync"
)

func main() {
	var mu sync.Mutex
	stock := 10

	// 判断库存和扣减必须在同一个临界区里完成
	buy := func() bool {
		mu.Lock()
		defer mu.Unlock()
		if stock <= 0 {
			return false
		}
		stock--
		return true
	}

	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			buy()
		}()
	}
	wg.Wait()
	fmt.Println("剩余库存", stock) // 不会变成负数
}

