import "fmt"

func main() {
	const shards = 10
	counts := make([]int64, shards)

	// 写：随机选一片累加，把热点 key 摊开
	for i := 0; i < 1000; i++ {
		counts[i%shards]++
	}

	// 读：把所有分片求和
	var total int64
	for _, c := range counts {
		total += c
	}
	fmt.Println(total) // 1000
}

package main

import (
	"fmt"
	"math/rand"
	"sync"
)

func main() {
	// 方式一：共享同一个 *Rand，所有调用都要加锁保护
	shared := rand.New(rand.NewSource(42))
	var mu sync.Mutex
	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			defer mu.Unlock()
			_ = shared.Intn(100)
		}()
	}
	wg.Wait()

	// 方式二：每个 goroutine 一个独立 Rand，互不共享就没有锁
	local := rand.New(rand.NewSource(7))
	fmt.Println(local.Intn(100), shared.Intn(100))
}

