import (
	"fmt"
	"sort"
)

// 两路归并：把两个有序片段合成一个有序片段
func merge(a, b []int) []int {
	out := make([]int, 0, len(a)+len(b))
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		if a[i] <= b[j] {
			out = append(out, a[i])
			i++
		} else {
			out = append(out, b[j])
			j++
		}
	}
	out = append(out, a[i:]...)
	return append(out, b[j:]...)
}

func main() {
	data := []int{5, 3, 9, 1, 7, 2, 8, 4}
	chunk := 3

	// 第一阶段：分块读入内存并各自排序，得到多个有序顺串
	var runs [][]int
	for i := 0; i < len(data); i += chunk {
		end := i + chunk
		if end > len(data) {
			end = len(data)
		}
		block := append([]int(nil), data[i:end]...)
		sort.Ints(block)
		runs = append(runs, block)
	}

	// 第二阶段：多路归并成最终结果
	result := runs[0]
	for _, r := range runs[1:] {
		result = merge(result, r)
	}
	fmt.Println(result) // [1 2 3 4 5 7 8 9]
}

