import (
	"fmt"
	"sync"
	"time"
)

// 简化版 Snowflake：时间戳 + 机器位 + 序列号
const (
	workerIDBits = 5
	seqBits      = 12
	maxWorkerID  = -1 ^ (-1 << workerIDBits)
	maxSeq       = -1 ^ (-1 << seqBits)
)

type snowflake struct {
	mu        sync.Mutex
	workerID  int64
	lastStamp int64
	seq       int64
}

func (s *snowflake) next() int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := time.Now().UnixMilli()
	if now == s.lastStamp {
		s.seq = (s.seq + 1) & maxSeq
		if s.seq == 0 {
			// 同一毫秒的序列用完了，等下一毫秒
			for now <= s.lastStamp {
				now = time.Now().UnixMilli()
			}
		}
	} else {
		s.seq = 0
	}
	s.lastStamp = now
	return (now << (workerIDBits + seqBits)) | (s.workerID << seqBits) | s.seq
}

func main() {
	g := &snowflake{workerID: 1}
	a := g.next()
	b := g.next()
	fmt.Println(a < b) // 趋势递增
}

