import (
	"fmt"
	"sort"
)

type rank struct {
	UserID string
	Score  int64
}

func main() {
	// 用 map + 排序模拟 Redis ZSet 的两个核心操作
	scores := map[string]int64{
		"u1": 100,
		"u2": 300,
		"u3": 200,
	}

	// ZINCRBY：给某个成员加分
	scores["u1"] += 50

	// ZREVRANGE：按分数倒序取前 N 名
	all := make([]rank, 0, len(scores))
	for id, s := range scores {
		all = append(all, rank{UserID: id, Score: s})
	}
	sort.Slice(all, func(i, j int) bool {
		if all[i].Score == all[j].Score {
			return all[i].UserID < all[j].UserID // 同分时用 member 字典序兜底
		}
		return all[i].Score > all[j].Score
	})
	fmt.Println(all[:2]) // Top 2
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	// 有界 channel：业务线程只负责投递，不等落盘
	ch := make(chan string, 1024)
	var wg sync.WaitGroup

	// 单独的 goroutine 攒批写盘
	wg.Add(1)
	go func() {
		defer wg.Done()
		buf := make([]string, 0, 64)
		for msg := range ch {
			buf = append(buf, msg)
			if len(buf) >= cap(buf) {
				fmt.Println("批量写入", buf)
				buf = buf[:0]
			}
		}
		if len(buf) > 0 {
			fmt.Println("批量写入", buf)
		}
	}()

	for i := 0; i < 100; i++ {
		ch <- fmt.Sprintf("log-%d", i)
	}
	close(ch)
	wg.Wait()
}

package main

import "fmt"

type message struct {
	Version int64
	Payload string
}

func main() {
	// 消费端收到乱序的消息，用版本号丢弃过期消息
	msgs := []message{
		{Version: 3, Payload: "余额更新到 30"},
		{Version: 1, Payload: "余额更新到 10"},
		{Version: 2, Payload: "余额更新到 20"},
	}

	var last int64
	for _, m := range msgs {
		if m.Version <= last {
			fmt.Println("丢弃过期消息", m.Payload)
			continue
		}
		last = m.Version
		fmt.Println("处理", m.Payload)
	}
}
